@SpringBootTest(properties={"app.roles=api","app.simulation-enabled=true","app.generic-ingest-enabled=true","app.storage=h2-dev","spring.datasource.url=jdbc:h2:mem:device-detail;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1"})
@AutoConfigureMockMvc @ActiveProfiles("test") @Import(DeviceDetailIntegrationTest.Observation.class)
class DeviceDetailIntegrationTest {
    static final OffsetDateTime T=OffsetDateTime.parse("2026-10-22T00:00:00.123456Z");
    @DynamicPropertySource static void environment(DynamicPropertyRegistry r){IngestionIntegrationTest.environment(r);}
    @TestConfiguration static class Observation {
        @Bean @Primary Clock deliberatelyDifferentClock(){return Clock.fixed(Instant.parse("2000-01-01T00:00:00Z"),ZoneOffset.UTC);}
        @Bean @Primary DeviceObserved observed(@Qualifier("dataSource")DataSource actual){return new DeviceObserved(actual);}
    }
    static class DeviceObserved extends AlarmWorkbenchIntegrationTest.ObservedDataSource {
        volatile Runnable onDevice;
        DeviceObserved(DataSource actual){super(actual);}
        private Object forward(Object target,Method method,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(InvocationTargetException e){throw e.getCause();}}
        @Override Connection wrap(Connection connection){var wrapped=super.wrap(connection);return (Connection)Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class[]{Connection.class},(proxy,method,args)->{Object value=forward(wrapped,method,args);if(method.getName().equals("prepareStatement")&&args!=null&&args[0] instanceof String sql&&sql.startsWith("SELECT ")&&sql.contains(" FROM devices d ")&&sql.contains("computed_connectivity")){return Proxy.newProxyInstance(PreparedStatement.class.getClassLoader(),new Class[]{PreparedStatement.class},(p,m,a)->{Object result=forward(value,m,a);if(m.getName().equals("executeQuery")&&onDevice!=null){var hook=onDevice;onDevice=null;hook.run();}return result;});}return value;});}
    }
    @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;@Autowired Bootstrap bootstrap;@Autowired JsonPointerParser parser;@Autowired DeviceQueryService devices;@Autowired AlarmWorkbenchQueries alarms;@Autowired DatabaseTime time;@Autowired TransactionRequirements transactions;@Autowired DeviceObserved observed;
    IngestionIntegrationTest f;
    @BeforeEach void reset()throws Exception{jdbc.update("DELETE FROM parameter_changes");jdbc.update("DELETE FROM parameter_overrides");f=new IngestionIntegrationTest();f.mvc=mvc;f.json=json;f.jdbc=jdbc;f.bootstrap=bootstrap;f.parser=parser;f.reset();jdbc.update("UPDATE numeric_settings SET setting_value=20,revision=0 WHERE setting_key='default_page_size'");jdbc.update("UPDATE numeric_settings SET setting_value=2880,revision=0 WHERE setting_key='offline_threshold_minutes'");jdbc.update("DELETE FROM parameter_changes");jdbc.update("DELETE FROM parameter_overrides");jdbc.update("INSERT INTO devices(id,tenant_id,name,device_eui,model,address,physical_state) VALUES ('device-c','tenant-a','Same current name','third-eui','legacy-model','Current location','UNKNOWN')");jdbc.update("UPDATE devices SET name='Same current name',address='Current location' WHERE id='device-a'");seed("alarm-a0","tenant-a","device-a",T,"FIRE","UNHANDLED",null,"Historic%_! <script>");seed("alarm-a1","tenant-a","device-a",T.plusSeconds(1),"NORMAL","HANDLED","TRUE_FIRE","Same historic name");seed("alarm-a2","tenant-a","device-a",T.plusSeconds(2),"NORMAL","UNHANDLED",null,"Other snapshot");seed("alarm-c0","tenant-a","device-c",T,"FIRE","UNHANDLED",null,"Historic%_! <script>");seed("alarm-b0","tenant-b","device-b",T,"FIRE","UNHANDLED",null,"Historic%_! <script>");observed.calls.clear();observed.onPage=null;observed.onDevice=null;}
    void seed(String id,String tenant,String device,OffsetDateTime at,String physical,String response,String conclusion,String name){jdbc.update("INSERT INTO alarms(id,tenant_id,device_id,device_name,address,event_type,occurred_at,physical_state,response_state,conclusion,remark,revision,is_simulated) VALUES (?,?,?,?,?,'FIRE',?,?,?,?, 'Private note',0,FALSE)",id,tenant,device,name,"Historical address",at,physical,response,conclusion);}
    ResultActions request(String token,String tenant,String id,String suffix,Map<String,String> query)throws Exception{var b=get("/api/management/devices/"+id+suffix).header("Authorization","Bearer "+token);if(tenant!=null)b.header("X-Tenant-Id",tenant);query.forEach(b::param);return mvc.perform(b);}
    JsonNode detail(String id)throws Exception{return f.body(request(f.root,"tenant-a",id,"",Map.of()).andExpect(status().isOk()));}
    JsonNode page(String id,Map<String,String> q)throws Exception{return f.body(request(f.root,"tenant-a",id,"/alarms",q).andExpect(status().isOk()));}
    AlarmWorkbenchFilter filter(String response){return AlarmWorkbenchFilter.parse("",null,response,null,null,null);}
    String customer()throws Exception{var token=f.login("customer-a",IngestionIntegrationTest.INITIAL,"customer");f.call(HttpMethod.POST,"/api/auth/change-password",token,null,null,Map.of("current_password",IngestionIntegrationTest.INITIAL,"new_password",PASSWORD)).andExpect(status().isNoContent());return f.login("customer-a",PASSWORD,"customer");}

    @Test void connectivityHistoryDoesNotPromoteHeartbeatsOrInventAnOfflineDuration()throws Exception {
        jdbc.update("INSERT INTO legacy_ingest_events(id,tenant_id,device_id,kind,method,params_json,observed_at,created_at) VALUES ('explicit-offline','tenant-a','device-a','OFFLINE','offline.scan','{}',?,?),('heartbeat-not-a-transition','tenant-a','device-a','HEARTBEAT','source.heartbeat','{}',?,?)",T,T,T.plusMinutes(2),T.plusMinutes(2));
        var history=f.body(request(f.root,"tenant-a","device-a","/connectivity-history",Map.of()).andExpect(status().isOk()));
        assertThat(history.get("total").asLong()).isEqualTo(1);
        assertThat(history.at("/items/0/state").asText()).isEqualTo("OFFLINE");
        assertThat(history.at("/items/0/duration_seconds").isNull()).isTrue();
        var csv=request(f.root,"tenant-a","device-a","/connectivity-history/export",Map.of("state","OFFLINE"))
            .andExpect(status().isOk()).andExpect(content().contentTypeCompatibleWith("text/csv")).andReturn().getResponse().getContentAsString();
        assertThat(csv).contains("离线,,PLATFORM_SCAN").doesNotContain("HEARTBEAT");
        assertThat(f.body(request(f.root,"tenant-a","device-a","/lifecycle",Map.of()).andExpect(status().isOk())).get("items").isArray()).isTrue();
        request(f.root,"tenant-a","device-b","/connectivity-history",Map.of()).andExpect(status().isNotFound());
        request(f.root,"tenant-a","device-b","/lifecycle",Map.of()).andExpect(status().isNotFound());
    }
    Map<String,List<Map<String,Object>>> facts(){var result=new LinkedHashMap<String,List<Map<String,Object>>>();for(String table:List.of("devices","device_battery_threshold_overrides","device_battery_threshold_changes","alarms","device_profile_snapshots","profile_rules","device_battery_observations","device_events","alarm_trace_entries","numeric_settings","parameter_overrides","parameter_changes","products","product_versions", "device_place_history", "device_version_history", "ingestion_sources","source_bindings","active_source_bindings","raw_messages","message_previews","device_task_applications","processing_tasks","processing_attempts","notification_automation_policies","notification_automation_changes","notification_automation_intents","notification_dispatches","notification_records","notification_attempts","notification_history","audit_log","idempotency_records","identity_command_records","app_users","sessions","user_permissions","user_tenant_grants"))result.put(table,jdbc.queryForList("SELECT * FROM "+table));return result;}
    @Test void exactFourFieldsUseDbClockAndPreserveLegacyNullsWithoutAnyPrivateDirectory()throws Exception{jdbc.update("UPDATE devices SET is_simulated=TRUE,integration_state='RETIRED_SIMULATION',last_message_at=NULL,battery_percent=NULL,physical_state='UNKNOWN' WHERE id='device-a'");var before=time.now();var result=detail("device-a");var after=time.now();assertThat(result.size()).isEqualTo(4);assertThat(result.get("timezone").asText()).isEqualTo("Asia/Shanghai");assertThat(result.get("consumer").asText()).isEqualTo("CONNECTIVITY_AND_OFFLINE_EVENTS");var at=OffsetDateTime.parse(result.get("as_of").asText());assertThat(at.getOffset()).isEqualTo(ZoneOffset.UTC);assertThat(at.toInstant()).isBetween(before.toInstant(),after.toInstant());assertThat(at.getNano()%1000).isZero();var row=result.get("device");assertThat(row.get("id").asText()).isEqualTo("device-a");assertThat(row.get("physical_state").asText()).isEqualTo("UNKNOWN");assertThat(row.get("connectivity").asText()).isEqualTo("UNACTIVATED");assertThat(row.get("integration_state").asText()).isEqualTo("RETIRED_SIMULATION");for(String key:List.of("battery_percent","last_message_at","product_id","product_version_id","product_name","version_number"))assertThat(row.get(key).isNull()).isTrue();assertThat(OffsetDateTime.parse(row.at("/offline_policy/evaluated_at").asText()).toInstant()).isEqualTo(at.toInstant());assertThat(row.at("/battery_policy/status").asText()).isEqualTo("NOT_CONFIGURED");assertThat(OffsetDateTime.parse(row.at("/battery_policy/evaluated_at").asText()).toInstant()).isEqualTo(at.toInstant());assertThat(result.toString()).doesNotContain("Private note","actor_id","reason","schema","capabilities","token","notification");}
    @Test void deviceReadAloneWorksForBothAudiencesAndAlarmReadCannotReplaceIt()throws Exception{var customer=customer();jdbc.update("DELETE FROM user_permissions WHERE permission<>'device:read'");detail("device-a");request(f.root,"tenant-a","device-a","/alarms",Map.of()).andExpect(status().isForbidden());f.call(HttpMethod.GET,"/api/customer/devices/device-a",customer,null,null,null).andExpect(status().isOk());f.call(HttpMethod.GET,"/api/customer/devices/device-a/alarms",customer,null,null,null).andExpect(status().isForbidden());jdbc.update("DELETE FROM user_permissions WHERE user_id='bootstrap-admin'");jdbc.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','alarm:read')");request(f.root,"tenant-a","device-a","",Map.of()).andExpect(status().isForbidden());request(f.root,"tenant-a","device-a","/alarms",Map.of()).andExpect(status().isForbidden());f.call(HttpMethod.GET,"/api/management/alarm-workbench",f.root,"tenant-a",null,null).andExpect(status().isOk());}
    @Test void preciseTenantOwnershipAndCustomerForgeryHaveNoEmptySuccessFallback()throws Exception{for(String suffix:List.of("","/alarms")){request(f.root,"tenant-a","device-b",suffix,Map.of()).andExpect(status().isNotFound());request(f.root,"tenant-a","missing",suffix,Map.of()).andExpect(status().isNotFound());request(f.root,null,"device-a",suffix,Map.of()).andExpect(status().isBadRequest());}var customer=customer();jdbc.update("INSERT INTO user_permissions(user_id,permission) SELECT id,'alarm:read' FROM app_users WHERE username='customer-a' AND NOT EXISTS(SELECT 1 FROM user_permissions p WHERE p.user_id=app_users.id AND p.permission='alarm:read')");for(String suffix:List.of("","/alarms")){f.call(HttpMethod.GET,"/api/customer/devices/device-a"+suffix,customer,null,null,null).andExpect(status().isOk());f.call(HttpMethod.GET,"/api/customer/devices/device-b"+suffix,customer,null,null,null).andExpect(status().isNotFound());f.call(HttpMethod.GET,"/api/customer/devices/device-a"+suffix,customer,"tenant-a",null,null).andExpect(status().isForbidden());}mvc.perform(get("/api/management/devices/device-a")).andExpect(status().isUnauthorized());}
    @Test void boundVersionIsFixedUntilExplicitMigrationAndNewFormalFactsStayUnknown()throws Exception{var product=f.product();var first=f.published(product.get("id").asText(),"1");var registered=f.register(first,false);String id=registered.get("id").asText();var second=f.published(product.get("id").asText(),"1");var before=detail(id).get("device");assertThat(before.get("product_version_id")).isEqualTo(first.get("id"));assertThat(before.get("version_number")).isEqualTo(first.get("version_number"));assertThat(before.get("model")).isEqualTo(product.get("model"));assertThat(before.get("physical_state").asText()).isEqualTo("UNKNOWN");assertThat(before.get("last_message_at").isNull()).isTrue();assertThat(before.get("battery_percent").isNull()).isTrue();f.call(HttpMethod.POST,"/api/management/devices/"+id+"/migrate-version",f.root,"tenant-a","detail-migrate",Map.of("product_version_id",second.get("id").asText(),"expected_revision",before.get("revision").asLong(),"reason","Explicit version migration")).andExpect(status().isOk());assertThat(detail(id).at("/device/product_version_id")).isEqualTo(second.get("id"));assertThat(page(id,Map.of()).get("total").asLong()).isZero();}
    @Test void livePolicyRefreshPreservesExactDecimalAndDeviceRevision()throws Exception{BigDecimal exact=new BigDecimal("0.10000000000000001");var reportAt=time.now().minusMinutes(10);jdbc.update("UPDATE devices SET battery_percent=?,last_message_at=? WHERE id='device-a'",exact,reportAt);jdbc.update("INSERT INTO legacy_ingest_events(id,tenant_id,device_id,kind,method,params_json,observed_at,created_at) VALUES ('detail-live-heartbeat','tenant-a','device-a','HEARTBEAT','source.heartbeat','{}',?,?)",reportAt,reportAt);var first=detail("device-a");assertThat(first.at("/device/connectivity").asText()).isEqualTo("ONLINE");var raw=request(f.root,"tenant-a","device-a","",Map.of()).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(raw).contains("\"battery_percent\":0.10000000000000001");var revision=first.at("/device/revision");f.call(HttpMethod.PUT,"/api/management/parameter-values/DEVICE/device-a/offline_threshold_minutes",f.root,"tenant-a","detail-threshold",Map.of("value",1,"expected_revision",0,"reason","Explicit query policy")).andExpect(status().isOk());var second=detail("device-a");assertThat(second.at("/device/connectivity").asText()).isEqualTo("OFFLINE");assertThat(second.at("/device/offline_policy/source_scope").asText()).isEqualTo("DEVICE");assertThat(second.at("/device/offline_policy/source_revision").asInt()).isEqualTo(1);assertThat(second.at("/device/revision")).isEqualTo(revision);jdbc.update("UPDATE devices SET battery_percent=0,last_message_at=NULL WHERE id='device-a'");assertThat(detail("device-a").at("/device/battery_percent").decimalValue()).isEqualByComparingTo(BigDecimal.ZERO);assertThat(detail("device-a").at("/device/connectivity").asText()).isEqualTo("UNACTIVATED");}
    @Test void associatedAlarmScopeUsesIdNotSameNamesAndPreservesHistoricalDisplay()throws Exception{var result=page("device-a",Map.of("size","1"));assertThat(result.size()).isEqualTo(10);assertThat(result.get("device_id").asText()).isEqualTo("device-a");assertThat(result.get("filters").size()).isEqualTo(6);assertThat(result.get("total").asLong()).isEqualTo(3);assertThat(result.at("/metrics/alarm_total").asLong()).isEqualTo(3);assertThat(result.at("/metrics/unhandled").asLong()).isEqualTo(2);assertThat(result.at("/metrics/handled").asLong()).isEqualTo(1);assertThat(result.at("/metrics/unrecovered").asLong()).isEqualTo(1);assertThat(result.at("/metrics/recovered").asLong()).isEqualTo(2);assertThat(result.at("/metrics/true_fire").asLong()).isEqualTo(1);var literal=page("device-a",Map.of("keyword","%_!"));assertThat(literal.get("items").size()).isEqualTo(1);assertThat(literal.at("/items/0/id").asText()).isEqualTo("alarm-a0");assertThat(literal.at("/items/0/device_name").asText()).isEqualTo("Historic%_! <script>");assertThat(detail("device-a").at("/device/name").asText()).isEqualTo("Same current name");assertThat(page("device-a",Map.of("keyword","Same current name")).get("total").asLong()).isZero();assertThat(page("device-c",Map.of()).get("total").asLong()).isEqualTo(1);}
    @Test void filteredAllPageMetricsAndMicrosecondBoundsNeverUseCurrentPageOrDefaultWindow()throws Exception{jdbc.update("UPDATE numeric_settings SET setting_value=5 WHERE setting_key='default_page_size'");var outside=page("device-a",Map.of("page","20"));assertThat(outside.get("size").asInt()).isEqualTo(5);assertThat(outside.get("items").isEmpty()).isTrue();assertThat(outside.get("total").asLong()).isEqualTo(3);assertThat(outside.at("/metrics/alarm_total").asLong()).isEqualTo(3);var exact=page("device-a",Map.of("occurred_from",T.toString(),"occurred_to",T.plusNanos(1000).toString()));assertThat(exact.get("total").asLong()).isEqualTo(1);assertThat(exact.at("/items/0/id").asText()).isEqualTo("alarm-a0");var impossible=page("device-a",Map.of("response_state","HANDLED","conclusion","UNREVIEWED"));assertThat(impossible.get("total").asLong()).isZero();assertThat(impossible.at("/metrics/true_fire").asLong()).isZero();}
    @Test void snapshotReadsUseRepeatableReadWithoutWrites(){var detail=devices.detail("bootstrap-admin","tenant-a","device-a");assertThat(observed.calls).isNotEmpty().allMatch(c->c.isolation()==Connection.TRANSACTION_REPEATABLE_READ);assertThat(detail.device().offlinePolicy().evaluatedAt()).isEqualTo(detail.asOf());observed.calls.clear();alarms.device("bootstrap-admin","tenant-a","device-a",1,1,filter(null));assertThat(observed.calls).isNotEmpty().allMatch(c->c.isolation()==Connection.TRANSACTION_REPEATABLE_READ);}
    @Test void writerAfterRealDeviceProjectionBeforeMappingKeepsWholeOldSnapshot()throws Exception{var reportAt=time.now().minusMinutes(10);jdbc.update("UPDATE devices SET last_message_at=? WHERE id='device-a'",reportAt);jdbc.update("INSERT INTO legacy_ingest_events(id,tenant_id,device_id,kind,method,params_json,observed_at,created_at) VALUES ('detail-snapshot-heartbeat','tenant-a','device-a','HEARTBEAT','source.heartbeat','{}',?,?)",reportAt,reportAt);var reached=new CountDownLatch(1);var committed=new CountDownLatch(1);observed.onDevice=()->{reached.countDown();try{if(!committed.await(10,TimeUnit.SECONDS))throw new AssertionError("Writer did not commit");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}};try(var pool=Executors.newSingleThreadExecutor()){var reading=pool.submit(()->devices.detail("bootstrap-admin", "tenant-a", "device-a"));assertThat(reached.await(10,TimeUnit.SECONDS)).isTrue();try{new TransactionTemplate(new DataSourceTransactionManager(observed)).executeWithoutResult(s->{jdbc.update("UPDATE devices SET name='Committed live name',revision=revision+1 WHERE id='device-a'");jdbc.update("UPDATE numeric_settings SET setting_value=1,revision=revision+1 WHERE setting_key='offline_threshold_minutes'");});}finally{committed.countDown();}var old=reading.get(10,TimeUnit.SECONDS);assertThat(old.device().name()).isEqualTo("Same current name");assertThat(old.device().offlinePolicy().value()).isEqualTo(2880);assertThat(old.device().connectivity()).isEqualTo("ONLINE");}var fresh=devices.detail("bootstrap-admin", "tenant-a", "device-a");assertThat(fresh.device().name()).isEqualTo("Committed live name");assertThat(fresh.device().offlinePolicy().value()).isEqualTo(1);assertThat(fresh.device().connectivity()).isEqualTo("OFFLINE");}
    @Test void realReviewBetweenDeviceAggregateAndPageKeepsCountersAndRowsCoherent()throws Exception{var reached=new CountDownLatch(1);var committed=new CountDownLatch(1);observed.onPage=()->{reached.countDown();try{if(!committed.await(10,TimeUnit.SECONDS))throw new AssertionError("Review did not commit");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}};try(var pool=Executors.newSingleThreadExecutor()){var reading=pool.submit(()->alarms.device("bootstrap-admin", "tenant-a", "device-a",1,100,filter("UNHANDLED")));assertThat(reached.await(10,TimeUnit.SECONDS)).isTrue();try{f.call(HttpMethod.POST,"/api/management/alarms/alarm-a0/review",f.root,"tenant-a","detail-review",Map.of("expected_revision",0,"conclusion","TRUE_FIRE","remark","Explicit review")).andExpect(status().isOk());}finally{committed.countDown();}var old=reading.get(10,TimeUnit.SECONDS);assertThat(old.total()).isEqualTo(2);assertThat(old.items()).hasSize(2);assertThat(old.metrics().unhandled()).isEqualTo(2);assertThat(old.items()).allMatch(a->a.deviceId().equals("device-a")&&a.responseState().equals("UNHANDLED"));}assertThat(alarms.device("bootstrap-admin", "tenant-a", "device-a",1,100,filter("UNHANDLED")).total()).isEqualTo(1);}
    @Test void outerReadCommittedOrWritableRrIsRejectedInsteadOfPretendingToUpgrade(){for(int isolation:new int[]{TransactionDefinition.ISOLATION_READ_COMMITTED,TransactionDefinition.ISOLATION_REPEATABLE_READ}){var tx=new TransactionTemplate(new DataSourceTransactionManager(observed));tx.setReadOnly(isolation==TransactionDefinition.ISOLATION_READ_COMMITTED);tx.setIsolationLevel(isolation);assertThatThrownBy(()->tx.execute(s->devices.detail("bootstrap-admin", "tenant-a", "device-a"))).isInstanceOfSatisfying(ApiError.class,e->assertThat(e.code).isEqualTo("TRANSACTION_ISOLATION_REQUIRED"));assertThatThrownBy(()->tx.execute(s->alarms.device("bootstrap-admin", "tenant-a", "device-a",1,20,filter(null)))).isInstanceOf(ApiError.class);}assertThatThrownBy(transactions::repeatableReadOnly).isInstanceOf(ApiError.class);}
    @Test void successfulReadsWriteNothingAndRejectedRequestsRetainSeparateDeniedAudit()throws Exception{var before=facts();for(int i=0;i<2;i++){detail("device-a");page("device-a",Map.of("size","1","page","20"));}assertThat(facts()).isEqualTo(before);long audit=jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Long.class);long denied=jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE outcome='DENIED'",Long.class);request(f.root,"tenant-a","device-b","",Map.of()).andExpect(status().isNotFound());assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Long.class)).isEqualTo(audit+1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE outcome='DENIED'",Long.class)).isEqualTo(denied+1);for(String suffix:List.of("","/alarms"))request(f.root,"tenant-a","device-a",suffix,Map.of("device_id","device-b")).andExpect(status().isBadRequest());mvc.perform(get("/api/management/devices/device-a/alarms").header("Authorization","Bearer "+f.root).header("X-Tenant-Id","tenant-a").param("size","1","2")).andExpect(status().isBadRequest());request(f.root,"tenant-a","device-a","/alarms",Map.of("occurred_from","2026-10-22T00:00")).andExpect(status().isBadRequest());request(f.root,"tenant-a","device-a","/alarms",Map.of("page","0")).andExpect(status().isBadRequest());f.call(HttpMethod.GET,"/api/auth/me",f.root,null,null,null).andExpect(status().isOk());}
}
